import terser from '@rollup/plugin-terser';
import { nodeResolve } from '@rollup/plugin-node-resolve';
import del from 'rollup-plugin-delete';
import { generateSW } from 'rollup-plugin-workbox';
import sizes from 'rollup-plugin-sizes';
import css from 'rollup-plugin-css-only';

const isProd = process.env.NODE_ENV === 'production';

// Two entry points, one per page type. Rollup builds the array in order, so
// the service worker is generated by the last config, after every bundle and
// page exists on disk, and precaches all of them.
export default [
	{
		input: 'src/js/index.js',
		output: { file: 'public/bundle.js', format: 'iife' },
		plugins: [
			del({
				targets: [
					'public/workbox-*.js',
					'public/workbox-*.js.map',
					'public/service-worker.js.map',
					'public/bundle.js',
					'public/bundle.css',
					'public/generator.js',
					'public/generator.css',
				],
			}),
			nodeResolve(),
			css({ output: 'bundle.css' }),
			terser(),
			sizes(),
		],
	},
	{
		input: 'src/js/generator.js',
		output: { file: 'public/generator.js', format: 'iife' },
		plugins: [
			nodeResolve(),
			css({ output: 'generator.css' }),
			terser(),
			isProd &&
				generateSW({
					swDest: 'public/service-worker.js',
					globDirectory: './public',
					sourcemap: false,
					clientsClaim: true,
					skipWaiting: true,
					runtimeCaching: [
						{
							urlPattern: isProd ? /https:\/\/qrcodescan.in\// : /http:\/\/localhost:5000\//,
							handler: 'StaleWhileRevalidate',
							options: {
								cacheName: 'pages',
								cacheableResponse: { statuses: [200] },
							},
						},
					],
				}),
			sizes(),
		],
	},
];
